import sys

def solve() -> None:
    data = sys.stdin.read().strip().splitlines()
    owners = {}          # lock -> txn
    queues = {}          # lock -> list of txn waiting
    out = []

    for line in data:
        if not line.strip():
            continue
        parts = line.strip().split()
        if len(parts) != 3:
            continue
        op, txn, lock = parts
        if op == "ACQ":
            owner = owners.get(lock)
            if owner is None:
                owners[lock] = txn
                out.append(f"GRANTED {txn} {lock}")
            elif owner == txn:
                out.append(f"ALREADY {txn} {lock}")
            else:
                q = queues.setdefault(lock, [])
                q.append(txn)
                out.append(f"WAIT {txn} {lock}")
        elif op == "REL":
            owner = owners.get(lock)
            if owner != txn:
                out.append(f"IGNORED {txn} {lock}")
                continue
            # release
            del owners[lock]
            q = queues.get(lock, [])
            if q:
                next_txn = q.pop(0)
                owners[lock] = next_txn
                # keep queue if empty? keep dict
                out.append(f"RELEASED {txn} {lock} GRANTED {next_txn} {lock}")
                if not q:
                    # optional cleanup
                    pass
            else:
                out.append(f"RELEASED {txn} {lock}")
        else:
            # unknown op, ignore
            continue

    sys.stdout.write("\n".join(out))

if __name__ == "__main__":
    solve()

